import{frameworkTool,interactionOnly}from"./framework-tool.js";import{defineJsonSchema}from"#tools/schema.js";import{defineWorkflowTool}from"#public/tools/index.js";import{INTERRUPTED_OUTPUT_SCHEMA,toInterruptibleModelOutput}from"#tools/provided/interrupted.js";import{executeSleepTool}from"#tools/provided/sleep-workflow.js";const SLEEP_INPUT_SCHEMA=defineJsonSchema({type:`object`,properties:{seconds:{type:`number`,exclusiveMinimum:0,maximum:Math.floor((2**53-1)/1e3),description:`How long to wait, in seconds.`}},required:[`seconds`],additionalProperties:!1}),SLEEP_OUTPUT_SCHEMA=defineJsonSchema({oneOf:[{type:`object`,properties:{waitedSeconds:{type:`number`,exclusiveMinimum:0}},required:[`waitedSeconds`],additionalProperties:!1},INTERRUPTED_OUTPUT_SCHEMA]}),sleep=frameworkTool(defineWorkflowTool({description:`Wait for a specified amount of time before continuing. Use this when a process or condition needs time to change before it is useful to check its progress or status again.`,execute:interactionOnly(executeSleepTool),inputSchema:SLEEP_INPUT_SCHEMA,outputSchema:SLEEP_OUTPUT_SCHEMA,toModelOutput:toInterruptibleModelOutput}));export{SLEEP_INPUT_SCHEMA,sleep};